contract InvMutTest {
    C c;

    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable {
        require(dummy == 0 || dummy > 0);
        uint256 balBefore = address(c).balance;
        bool settleReverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            settleReverted = true;
        } else {
            settleReverted = false;
        }
        assert(settleReverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

